function walk(value, visit, seen = new Set()) {
  if (value === null || value === undefined) return;
  if (typeof value !== 'object') return;
  if (seen.has(value)) return;
  seen.add(value);
  if (Array.isArray(value)) {
    for (const item of value) walk(item, visit, seen);
    return;
  }
  for (const [key, child] of Object.entries(value)) {
    visit(key, child, value);
    walk(child, visit, seen);
  }
}

const payload = items[0]?.json || {};
let chatId = null;
let placeholderMessageId = null;
let route = '';
let userMessage = '';
let errorText = '';
let failedNode = '';

walk(payload, (key, child, parent) => {
  if (chatId === null && key === 'chat_id') {
    const asNumber = Number(child);
    if (Number.isFinite(asNumber) && asNumber > 0) chatId = asNumber;
  }
  if (placeholderMessageId === null && key === 'placeholder_message_id') {
    const asNumber = Number(child);
    if (Number.isFinite(asNumber) && asNumber > 0) placeholderMessageId = asNumber;
  }
  if (!route && key === 'route' && typeof child === 'string') {
    route = child;
  }
  if (!userMessage && key === 'user_message' && typeof child === 'string') {
    userMessage = child;
  }
  if (!failedNode && key === 'name' && parent && typeof parent.type === 'string') {
    failedNode = String(child);
  }
  if (!errorText && key === 'message' && parent && (parent.name === 'NodeApiError' || parent.name === 'ExecutionError')) {
    errorText = String(child);
  }
});

const summary = errorText || String(payload.execution?.error?.message || payload.error?.message || 'workflow_error');
const normalized = summary.toLowerCase();
const isPollingConflict = normalized.includes('terminated by other getupdates request') || normalized.includes('conflict: terminated by other getupdates request');
const shouldNotify = Number.isFinite(Number(chatId)) && Number(chatId) > 0 && !isPollingConflict;
const text = 'Извини, я временно потерял связь со своими инструментами. Попробуй через минуту.';

return [{
  json: {
    ...payload,
    chat_id: chatId,
    placeholder_message_id: placeholderMessageId,
    route: route || 'error_handler',
    user_message: userMessage || '',
    failed_node: failedNode || null,
    error_summary: summary,
    should_notify: shouldNotify,
    assistant_reply: text,
    telegram_error_method: placeholderMessageId ? 'editMessageText' : 'sendMessage',
  },
}];
